var n=`1333-arroz-con-pollo-peruano`;var t=`world-1333`;var a=`PE`;var o=`south-america`;var r=4;var s=83;var c={en:`Arroz con Pollo Peruano`,ua:`Рис із куркою по-перуанськи`};var g={en:`Arroz con Pollo Peruano is a dish from Peru featuring chicken thigh, cilantro, garlic, aji amarillo paste. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Рис із куркою по-перуанськи, страва кухні країни Перу з такими основними складниками: куряче стегно, кінза, часник, паста ахі амарильйо. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`chicken-thigh`,800,`g`],[`cilantro`,100,`g`],[`garlic`,5,`clove`],[`aji-amarillo-paste`,45,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,160,`g`],[`green-bell-pepper`,160,`g`],[`canola-oil`,45,`ml`]]},{en:`Add rinsed rice, stock, vegetables and the marinated chicken to a covered pot; cook until rice is tender and chicken reaches 74°C.`,ua:`Додайте промитий рис, бульйон, овочі та мариновану курку до каструлі з кришкою; готуйте до м’якості рису та 74°C у курці.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`white-rice`,450,`g`],[`chicken-stock`,850,`ml`],[`frozen-green-peas`,150,`g`],[`carrot`,200,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,1,`pcs`]]}];var h={slug:n,id:t,country:`PE`,region:o,servings:4,minutes:83,title:c,text:g,steps:l};export{a as country,h as default,t as id,s as minutes,o as region,r as servings,n as slug,l as steps,g as text,c as title};